import axios from "axios";
import { setupInterceptorsTo } from "./interceptors";

/**
 * Creates an axios instance for a specific service with enhanced interceptors
 * @param {string} options - Additional interceptor options
 * @param {Object} axiosConfig - Additional axios configuration
 * @returns {Object} Configured axios instance
 */
export const createAxiosInstance = (
    options = {},
    axiosConfig = {}
) => {
    // 1. Ambil URL dari environment variable
    // Jika di laptop (development), biasanya http://localhost:5000
    // Jika di server, pastikan di cPanel/Vercel sudah diset variabel ini
    const baseUrl = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

    const instance = axios.create({
        // 2. Gunakan variabel baseUrl agar dinamis
        baseURL: `${baseUrl}/api`, 
        headers: {
            "Content-Type": "application/json",
            "Cache-Control": "no-cache, no-store, must-revalidate",
            "Pragma": "no-cache",
            "Expires": "0",
        },
        ...axiosConfig,
    });

    setupInterceptorsTo(instance, {
        disableErrorToast: true,
        ...options,
    });

    return instance;
};